// Custom Cloudflare Worker entry: wraps the OpenNext worker and adds a
// scheduled handler that replaces the Vercel cron from vercel.json
// (/api/cron/bronnen-archief, daily 05:00 UTC). The route itself still checks
// the Bearer CRON_SECRET, so the request is handled exactly like before.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as openNextWorker } from "./.open-next/worker.js";

interface CronEnv {
  CRON_SECRET?: string;
}

const CRON_ROUTES: Record<string, string> = {
  "0 5 * * *": "/api/cron/bronnen-archief",
};

const worker = {
  fetch: openNextWorker.fetch,

  async scheduled(
    controller: { cron: string; scheduledTime: number },
    env: CronEnv,
    ctx: { waitUntil(promise: Promise<unknown>): void }
  ) {
    const path = CRON_ROUTES[controller.cron];
    if (!path || !env.CRON_SECRET) {
      console.error("cron: no route or CRON_SECRET for", controller.cron);
      return;
    }
    const request = new Request("https://facula-app.dgdh-os.workers.dev" + path, {
      headers: { authorization: "Bearer " + env.CRON_SECRET },
    });
    const run = Promise.resolve(openNextWorker.fetch(request, env, ctx)).then(
      async (response: Response) => {
        const body = await response.text();
        console.log("cron", path, response.status, body.slice(0, 300));
      }
    );
    ctx.waitUntil(run);
    await run;
  },
};

export default worker;
